local SundialMaker = {}
local PRODUCTS = {
    simple_stone_sundial = { name = "Preprost kamnit sončna ura", stoneCost = 2, time = 3, cost = 40, beauty = 18, education = 12, happiness = 1, description = "Preprosta kamnita sončna ura za trg." },
    bronze_ornate_sundial = { name = "Bronasta okrasna sončna ura", stoneCost = 1, bronzeCost = 2, time = 6, cost = 130, beauty = 35, education = 25, happiness = 2, prestige = 2, description = "Bronasta okrasna sončna ura za trgovce." },
    marble_pocket_sundial = { name = "Marmornat žepni sončnica", marbleCost = 2, brassCost = 1, time = 9, cost = 320, beauty = 50, education = 38, happiness = 2, prestige = 6, description = "Marmornat žepni sončnica za plemiče." },
    silver_compass_sundial = { name = "Srebrna kompasna sončna ura", marbleCost = 2, silverCost = 2, brassCost = 1, time = 12, cost = 760, beauty = 65, education = 52, happiness = 3, prestige = 14, description = "Srebrna kompasna sončna ura za visoke plemiče." },
    gold_inlaid_sundial = { name = "Zlatovložena sončna ura", marbleCost = 2, goldCost = 2, silverCost = 1, brassCost = 1, jewelCost = 1, time = 16, cost = 1700, beauty = 78, education = 68, happiness = 5, prestige = 27, description = "Zlatovložena sončna ura z draguljem za visoko plemstvo." },
    royal_grand_sundial = { name = "Kraljevski veliki sončna ura", marbleCost = 3, goldCost = 3, silverCost = 2, brassCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3900, beauty = 92, education = 88, happiness = 12, prestige = 58, description = "Velika kraljevska sončna ura z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    sundial_workshop = { name = "Sončna delavnica", cost = { gold = 220, wood = 100, stone = 120, brass = 6 }, upkeep = 5, qualityBonus = 5 },
    gnomon_loft = { name = "Gnomonska podstrešje", cost = { gold = 800, wood = 240, stone = 280, marble = 4, brass = 8 }, upkeep = 18, qualityBonus = 18 },
    master_horology_atelier = { name = "Mojstrski horološki atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_sundial_palace = { name = "Kraljevska sončna palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
SundialMaker.stoneStock = 16; SundialMaker.marbleStock = 12; SundialMaker.bronzeStock = 10; SundialMaker.brassStock = 10; SundialMaker.silverStock = 6; SundialMaker.goldStock = 6; SundialMaker.jewelStock = 4; SundialMaker.pearlStock = 4
SundialMaker.productStock = {}; SundialMaker.buildings = {}; SundialMaker.maker = nil; SundialMaker.activeMaking = {}; SundialMaker.totalProducts = 0; SundialMaker.dayTimer = 0
function SundialMaker.init() SundialMaker.stoneStock=16; SundialMaker.marbleStock=12; SundialMaker.bronzeStock=10; SundialMaker.brassStock=10; SundialMaker.silverStock=6; SundialMaker.goldStock=6; SundialMaker.jewelStock=4; SundialMaker.pearlStock=4; SundialMaker.productStock={}; SundialMaker.buildings={}; SundialMaker.maker=nil; SundialMaker.activeMaking={}; SundialMaker.totalProducts=0; SundialMaker.dayTimer=0; print("[SundialMaker] Royal Sundial Maker System initialized (6 products, 4 buildings)") end
function SundialMaker.hireMaker(n,s) s=s or math.random(55,90); local c=480+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SundialMaker.maker={name=n or ("Sončar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sončar najet: %s (spretnost: %d)",SundialMaker.maker.name,s),"success") end; return true end
function SundialMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SundialMaker.build(id) local ok,e=SundialMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SundialMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SundialMaker.getQualityBonus() local b=0; for _,bd in ipairs(SundialMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SundialMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.stoneCost and SundialMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.marbleCost and SundialMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.bronzeCost and SundialMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.brassCost and SundialMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and SundialMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SundialMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SundialMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SundialMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SundialMaker.buildings==0 then return false,"Potrebna sončna delavnica" end; if not SundialMaker.maker then return false,"Potreben sončar" end; return true end
function SundialMaker.make(pt,qty) qty=qty or 1; local ok,e=SundialMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.stoneCost then SundialMaker.stoneStock=SundialMaker.stoneStock-d.stoneCost*qty end; if d.marbleCost then SundialMaker.marbleStock=SundialMaker.marbleStock-d.marbleCost*qty end; if d.bronzeCost then SundialMaker.bronzeStock=SundialMaker.bronzeStock-d.bronzeCost*qty end; if d.brassCost then SundialMaker.brassStock=SundialMaker.brassStock-d.brassCost*qty end; if d.silverCost then SundialMaker.silverStock=SundialMaker.silverStock-d.silverCost*qty end; if d.goldCost then SundialMaker.goldStock=SundialMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SundialMaker.jewelStock=SundialMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SundialMaker.pearlStock=SundialMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SundialMaker.maker then t=math.max(1,t-math.floor(SundialMaker.maker.skill/13)) end; table.insert(SundialMaker.activeMaking,{id="sundial_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,education=d.education or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SundialMaker.completeMaking(m) local q=1.0+(SundialMaker.getQualityBonus()/100); if SundialMaker.maker then q=q+(SundialMaker.maker.skill/150) end; q=math.min(2.4,q); SundialMaker.productStock[m.productType]=(SundialMaker.productStock[m.productType] or 0)+m.quantity; SundialMaker.totalProducts=SundialMaker.totalProducts+m.quantity; if m.education>0 and _G.state then _G.state.education=(_G.state.education or 0)+m.education end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SundialMaker.maker then SundialMaker.maker.itemsMade=SundialMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SundialMaker.maker.skill=math.min(100,SundialMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sončna ura izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sundial.completed",{productName=m.productName,beauty=m.beauty,education=m.education,prestige=m.prestige,happiness=m.happiness}) end end
function SundialMaker.update(dt) if not _G.state then return end; SundialMaker.dayTimer=SundialMaker.dayTimer+dt; if SundialMaker.dayTimer>=30 then SundialMaker.dayTimer=0; for i=#SundialMaker.activeMaking,1,-1 do local m=SundialMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SundialMaker.completeMaking(m); table.remove(SundialMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SundialMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SundialMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SundialMaker.getStats() return {stoneStock=SundialMaker.stoneStock,marbleStock=SundialMaker.marbleStock,bronzeStock=SundialMaker.bronzeStock,brassStock=SundialMaker.brassStock,silverStock=SundialMaker.silverStock,goldStock=SundialMaker.goldStock,jewelStock=SundialMaker.jewelStock,pearlStock=SundialMaker.pearlStock,productStock=SundialMaker.productStock,numBuildings=#SundialMaker.buildings,hasMaker=SundialMaker.maker~=nil,makerName=SundialMaker.maker and SundialMaker.maker.name or "—",makerSkill=SundialMaker.maker and SundialMaker.maker.skill or 0,activeMaking=#SundialMaker.activeMaking,totalProducts=SundialMaker.totalProducts} end
return SundialMaker
